-- Create "proposal_generations" table
-- One row per generation of a measurement's sampling proposal. The vectors are stored whole,
-- in reviewed_area_ids order, because they are only ever read whole and in order.
CREATE TABLE "core"."proposal_generations" (
  "proposal_generation_id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "active_measurement_id" integer NOT NULL,
  "generation" integer NOT NULL,
  "n_labels" integer NOT NULL DEFAULT 0,
  "model_id" integer NULL,
  "alpha" double precision NULL,
  "reviewed_area_ids" integer[] NOT NULL,
  "raw" double precision[] NOT NULL,
  "proposal" double precision[] NOT NULL,
  "created" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "modified" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "uuid" uuid NOT NULL DEFAULT gen_random_uuid(),
  PRIMARY KEY ("proposal_generation_id"),
  CONSTRAINT "proposal_generations_active_measurement_id_generation_key" UNIQUE ("active_measurement_id", "generation"),
  CONSTRAINT "proposal_generations_active_measurement_id_fkey" FOREIGN KEY ("active_measurement_id") REFERENCES "projectmanagement"."active_measurements" ("active_measurement_id") ON UPDATE CASCADE ON DELETE CASCADE DEFERRABLE,
  CONSTRAINT "proposal_generations_model_id_fkey" FOREIGN KEY ("model_id") REFERENCES "projectmanagement"."models" ("model_id") ON UPDATE CASCADE ON DELETE SET NULL DEFERRABLE
);
-- Create index "proposal_generations_active_measurement_id_idx" to table: "proposal_generations"
CREATE INDEX "proposal_generations_active_measurement_id_idx" ON "core"."proposal_generations" ("active_measurement_id");
-- Create index "proposal_generations_uuid_idx" to table: "proposal_generations"
CREATE INDEX "proposal_generations_uuid_idx" ON "core"."proposal_generations" ("uuid");
